//! Code-only repair of the three fresh markets. Offline; no submission code.
use anyhow::{ensure,Result};
use std::{env,fs,io::Write};
use plonky2::field::{goldilocks_field::GoldilocksField as F,types::PrimeField64};
use psy_client_common::data::qhashout::QHashOut;
use psy_client_data::{config::store_config::{C,D,PsyHasher},qblock::cmds::deploy_contract::QBCUpdateContract};
use psy_compiler::output::serialize::{CompilationArtifact,ContractOutput};
use psy_prover::session::{gen_contract_update_and_circuits_for_functions,compile_bridge::build_layout_aware_update_command};
use psy_plonky2_circuits::{coordinator::state_layout_helper::CanonicalLayoutProofVerifier,utils::proof_serialization::deserialize_plonky2_proof};
use psy_core::constants::protocol::{STATE_LAYOUT_TREE_HEIGHT,STATE_LAYOUT_APPEND_SUB_TREE_HEIGHT,STATE_LAYOUT_MAX_AGGREGATION_DEPTH};
fn save(p:&str,v:&impl serde::Serialize)->Result<()>{let mut f=fs::OpenOptions::new().write(true).create_new(true).open(p)?;f.write_all(&serde_json::to_vec(v)?)?;Ok(())}
fn main()->Result<()>{let a:Vec<String>=env::args().collect();ensure!(a.len()==7,"prepare|verify old-artifact new-artifact old-included.json contract-id output-or-request [report via output argument on verify]");let old:CompilationArtifact=serde_json::from_slice(&fs::read(&a[2])?)?;let new:CompilationArtifact=serde_json::from_slice(&fs::read(&a[3])?)?;let old_record:serde_json::Value=serde_json::from_slice(&fs::read(&a[4])?)?;let leaf=&old_record["leaf"];let id:u64=a[5].parse()?;ensure!([2434,2435,2436].contains(&id),"only freshly created market repair allowed");ensure!(old_record["marker"]["contract_id"].as_u64()==Some(id),"old receipt ID mismatch");ensure!(serde_json::to_value(&old.abi)?==serde_json::to_value(&new.abi)? && old.state_tree_height==31 && new.state_tree_height==31,"ABI/layout must remain identical");let deployer=leaf["deployer"].as_u64().ok_or_else(||anyhow::anyhow!("numeric deployer user ID required"))?;ensure!(deployer>0&&deployer<(1u64<<32),"numeric owner bounds");
 let(_,base)=gen_contract_update_and_circuits_for_functions::<C,D>(id,deployer,31,&new.circuit_definitions)?;
 let(_,old_code)=gen_contract_update_and_circuits_for_functions::<C,D>(id,deployer,31,&old.circuit_definitions)?;
 ensure!(old_code.code_root.to_string()==leaf["code_root"].as_str().unwrap(),"old bytecode identity mismatch");
 let old_out=ContractOutput{contract_code:old_code.code_definition,circuit_definitions:old.circuit_definitions,abi:old.abi};let new_out=ContractOutput{contract_code:base.code_definition.clone(),circuit_definitions:new.circuit_definitions,abi:new.abi};
 let cmd=if a[1]=="prepare"{build_layout_aware_update_command(&old_out,&new_out,base.clone())?}else{ensure!(a[1]=="verify","mode");serde_json::from_slice::<QBCUpdateContract<F>>(&fs::read(&a[6])?)?};
 cmd.validate_shape()?;ensure!(cmd.contract_id==id&&cmd.deployer==deployer&&cmd.code_root==base.code_root&&cmd.code_definition==base.code_definition&&cmd.function_whitelist==base.function_whitelist,"candidate code/owner/ID mismatch");
 let verifier=CanonicalLayoutProofVerifier::<C,D>::new(STATE_LAYOUT_TREE_HEIGHT-STATE_LAYOUT_APPEND_SUB_TREE_HEIGHT,STATE_LAYOUT_APPEND_SUB_TREE_HEIGHT,STATE_LAYOUT_MAX_AGGREGATION_DEPTH);ensure!(cmd.canonical_layout_verifier_fingerprint.0.elements==verifier.fingerprint().0.elements,"verifier mismatch");verifier.verify_serialized_proof(&cmd.canonical_layout_proof)?;let proof=deserialize_plonky2_proof::<C,D>(&cmd.canonical_layout_proof)?;let p=&proof.public_inputs;ensure!(p.len()==19&&p[0].to_canonical_u64()==id&&p[1].to_canonical_u64()==cmd.layout_protocol_version as u64,"PI ID/version mismatch");
 let root=leaf["state_layout_root"].as_str().unwrap().parse::<QHashOut<F>>()?;let fields=leaf["state_layout_field_count"].as_u64().unwrap();let slots=leaf["state_layout_slot_count"].as_u64().unwrap();ensure!(cmd.state_layout_root==root&&cmd.state_layout_field_count==fields&&cmd.state_layout_slot_count==slots,"request differs from old live layout");ensure!(p[2..6]==root.0.elements&&p[8..12]==root.0.elements&&p[6].to_canonical_u64()==fields&&p[12].to_canonical_u64()==fields&&p[7].to_canonical_u64()==slots&&p[13].to_canonical_u64()==slots&&p[14].to_canonical_u64()==0,"identity-layout endpoints mismatch");
 let rooted=cmd.clone().into_with_whitelist_root::<PsyHasher>()?;let tx_hash=psy_crypto::hash::tx_hash::compute_update_contract_content_hash(id,rooted.deployer,&rooted.function_whitelist_root.to_le_bytes(),31);let content_hash=tx_hash.iter().map(|b|format!("{b:02x}")).collect::<String>();
 if a[1]=="prepare"{save(&a[6],&cmd)?;}else{save(&format!("{}.verified.json",a[6]),&serde_json::json!({"codeOnlyUpdateVerified":true,"expectedContentHash":content_hash,"contractId":id,"oldCodeRoot":leaf["code_root"],"newCodeRoot":cmd.code_root.to_string(),"layoutRoot":root.to_string(),"oldFieldCount":fields,"newFieldCount":fields,"oldSlotCount":slots,"newSlotCount":slots,"appendedFields":0,"proofBytes":cmd.canonical_layout_proof.len(),"submitted":false}))?;}
 println!("verified code-only identity layout for contract {id}; {fields} -> {fields}; NOT submitted");Ok(())}
